/**
 * Tone pairs and Tone changes (Pinyin sounds pages): browser-safe data model and URL rules.
 *
 * Data: src/data/pinyin/tone-pairs.json, generated by scripts/import-tone-pairs.py from the
 * owner's handoff (importer/data/tone-pairs/). It is loaded lazily (loadTonePairs) so the
 * 48 examples never enter a page bundle. Each example keeps three separate layers that must
 * never be mixed: the exact Shtooka source reading bound to its whole-word recording, the
 * authored dictionary (citation) tones, and the *expected in speech* tones, which are an
 * unreviewed teaching draft (e.g. 3+3 heard as 2+3). Grouping always uses the dictionary
 * pair, so 水果 stays in the 3 + 3 cell; 一/不 examples live only under Tone changes.
 * Neutral tone is stored as 5 and shown as "neutral" (a dot in compact cells).
 *
 * URL search (validated here, owned by the routes): pair / rule, exact example id,
 * listen=1 (Listen first: word names hidden). Playback speed is the app-wide "Slower
 * pronunciation" preference, not part of the URL (older speed=slow links are dropped).
 */

export type PairTone = 1 | 2 | 3 | 4 | 5;
export type ToneRule = 'third' | 'yi' | 'bu';
export type TonePairExample = {
  id: string; sourceFileIds: string[]; headword: string; sourceReading: string;
  citationSyllables: string[]; citationTones: PairTone[];
  expectedSpokenSyllables: string[]; expectedSpokenTones: PairTone[];
  pair: string; rule: ToneRule | null; inPairMatrix: boolean; english: string;
  reviewStatus: string; vocabularyEntryId: string | null;
  chartLinks: { reading: string; base: string; tone: PairTone }[];
  audio: { url: string; upstreamUrl?: string; speaker: string; source: string; license: string; licenseUrl: string; recordingKind: string; sha256?: string };
};
export type TonePairData = {
  reviewStatus: string; acquiredOn: string;
  source: { repository: string; commit: string; speaker: string; collection: string; copyright: string; license: string; licenseUrl: string; processingCredits: string };
  examples: TonePairExample[];
};

export const FIRST_TONES = [1, 2, 3, 4] as const;
export const SECOND_TONES = [1, 2, 3, 4, 5] as const;
export const DEFAULT_PAIR = '3-3';
export const DEFAULT_RULE: ToneRule = 'third';

/** Authored teaching copy for the three tone-change focus areas (from the owner's prototype). */
export const TONE_RULES: Record<ToneRule, { symbol: string; hanzi: boolean; title: string; short: string; description: string; detail: string }> = {
  third: { symbol: '3 + 3', hanzi: false, title: 'Two third tones', short: '3 + 3 becomes 2 + 3', description: 'The first third tone takes a rising form before another third tone.', detail: 'Listen for the first syllable rising into the second. Its dictionary identity stays third tone.' },
  yi: { symbol: '一', hanzi: true, title: 'The tone of 一', short: '1 becomes 2 or 4', description: 'Usually yí before tone 4; yì before tones 1, 2 and 3.', detail: 'These examples illustrate common contextual readings of 一. Counting and ordinal uses can retain yī.' },
  bu: { symbol: '不', hanzi: true, title: 'The tone of 不', short: '4 + 4 becomes 2 + 4', description: 'Usually bú before another fourth tone; bù before other full tones.', detail: 'Compare 不要 and 不错 with 不行. The word’s source reading remains attached to its whole-word recording.' },
};
export const RULE_ORDER: ToneRule[] = ['third', 'yi', 'bu'];

const PAIR_RE = /^[1-4]-[1-5]$/;
export const isPair = (value: unknown): value is string => typeof value === 'string' && PAIR_RE.test(value);
export const isRule = (value: unknown): value is ToneRule => value === 'third' || value === 'yi' || value === 'bu';

export type ToneSoundsSearch = { example?: string | undefined; listen?: true | undefined };
export type TonePairsSearch = ToneSoundsSearch & { pair?: string | undefined };
export type ToneChangesSearch = ToneSoundsSearch & { rule?: ToneRule | undefined; closed?: true | undefined };

/** Shared part of both validators: unknown values are dropped, never guessed. */
function common(search: Record<string, unknown>): ToneSoundsSearch {
  const out: ToneSoundsSearch = {};
  const example = search['example'];
  if (typeof example === 'string' && example.trim()) out.example = example;
  // The router may parse listen=1 as a number.
  const listen = search['listen'];
  if (listen === 1 || listen === '1' || listen === true) out.listen = true;
  return out;
}
export function validateTonePairsSearch(search: Record<string, unknown>): TonePairsSearch {
  const out: TonePairsSearch = common(search);
  if (isPair(search['pair'])) out.pair = search['pair'];
  return out;
}
export function validateToneChangesSearch(search: Record<string, unknown>): ToneChangesSearch {
  const out: ToneChangesSearch = common(search);
  if (isRule(search['rule'])) out.rule = search['rule'];
  // Closing hides the window without discarding the URL's exact rule/example.
  if (search['closed'] === true || search['closed'] === 1 || search['closed'] === '1') out.closed = true;
  return out;
}

/** Ordinary matrix examples for one dictionary pair (一/不 examples never appear here). */
export const pairPool = (data: Pick<TonePairData, 'examples'>, pair: string) => data.examples.filter(e => e.inPairMatrix && e.pair === pair);
/** Matrix pairs in reading order (first tone down the side, second across the top), limited to
 * the pairs `hasExamples` reports as non-empty: the card's middle-top ‹ › walk never lands on an
 * empty cell, so no navigation can show "Loading words…". */
export function matrixPairOrder(hasExamples: (pair: string) => boolean): string[] {
  const keys: string[] = [];
  for (const first of FIRST_TONES) for (const second of SECOND_TONES) {
    const key = `${first}-${second}`;
    if (hasExamples(key)) keys.push(key);
  }
  return keys;
}
/** Examples for one tone change: the two 3 + 3 matrix words, or the 一 / 不 sets. */
export const rulePool = (data: Pick<TonePairData, 'examples'>, rule: ToneRule) => data.examples.filter(e => e.rule === rule);
/** The URL's exact example when it belongs to this pool, otherwise the pool's first word. */
export const selectedExample = (pool: readonly TonePairExample[], id: string | undefined) => pool.find(e => e.id === id) ?? pool[0] ?? null;
/** Next word in the pool, wrapping round (Next word never plays by itself). */
export function nextExample(pool: readonly TonePairExample[], id: string): TonePairExample | null {
  if (!pool.length) return null;
  const index = pool.findIndex(e => e.id === id);
  return pool[(index + 1) % pool.length] ?? null;
}

export const toneName = (tone: number) => tone === 5 ? 'neutral' : String(tone);
/** "3 + neutral" style label for a tone list. */
export const toneLabel = (tones: readonly number[]) => tones.map(toneName).join(' + ');
export const pairLabel = (pair: string) => toneLabel(pair.split('-').map(Number));
/** True when the expected spoken draft differs from the dictionary tones (3+3 → 2+3, 一/不). */
export const tonesChanged = (e: Pick<TonePairExample, 'citationTones' | 'expectedSpokenTones'>) => e.citationTones.join() !== e.expectedSpokenTones.join();

/** The listening tip under a word: the rule's own detail, otherwise one by tone shape. */
export function listeningTip(e: TonePairExample): string {
  if (e.rule) return TONE_RULES[e.rule].detail;
  if (e.citationTones[1] === 5) return 'The second syllable is neutral. Listen to its short, light delivery after the first tone.';
  if (e.citationTones[0] === 3) return 'The first third tone is often low here, without the full rise heard in isolation.';
  return 'Listen once, pause, then say the whole word. Play each dictionary sound below to compare the syllables on their own.';
}

let loading: Promise<TonePairData> | null = null;
/** Lazily load the sidecar; a failed load can be retried. */
export function loadTonePairs(): Promise<TonePairData> {
  loading ??= Promise.all([
    import('@/data/pinyin/tone-pairs.json'), import('./mandarin'),
    import('./pinyin-guide').then(m => m.loadSyllableInventory()), import('./tone-pair-vocabulary'),
  ]).then(([m, vocabulary, syllables, adapter]) => adapter.enrichTonePairs(m.default as unknown as TonePairData, vocabulary.words, syllables))
    .catch(error => { loading = null; throw error; });
  return loading;
}
